const crypto = require('crypto');
const sign = (secret, timestamp, body) =>
  'v1=' + crypto.createHmac('sha256', secret).update(timestamp + '.' + body).digest('hex');
const signedRequest = (path, bodyObject) => {
  const secret = $env.LENDLOOP_INBOUND_SECRET;
  if (!secret) throw new Error('LENDLOOP_INBOUND_SECRET is not set');
  const base = String($env.LENDLOOP_CONVEX_SITE_URL || 'http://convex-backend:3211').replace(/\/+$/, '');
  const timestamp = String(Math.floor(Date.now() / 1000));
  const body = JSON.stringify(bodyObject);
  return {
    url: base + path,
    body,
    headers: {
      'Content-Type': 'application/json',
      'X-LendLoop-Timestamp': timestamp,
      'X-LendLoop-Signature': sign(secret, timestamp, body),
      'X-LendLoop-Event-Id': bodyObject.idempotencyKey || ''
    }
  };
};
const data = $input.first().json;
const execution = data.execution || {};
const workflowName = (data.workflow && data.workflow.name) || 'unknown workflow';
const nodeName = execution.lastNodeExecuted || undefined;
const message = String((execution.error && execution.error.message) || 'unknown error').slice(0, 500);
const idempotencyKey = 'workflow-error:' + (execution.id || workflowName + ':' + Date.now());
const request = signedRequest('/n8n/workflow-error', { idempotencyKey, workflowName, nodeName, executionId: execution.id ? String(execution.id) : undefined, message });
return [{ json: {
  ...request,
  subject: 'LendLoop workflow failed: ' + workflowName,
  text: 'Workflow: ' + workflowName + '\nNode: ' + (nodeName || 'n/a') + '\nExecution: ' + (execution.id || 'n/a') + '\nError: ' + message
} }];
